import time, threading, os, select
NB=os.O_NONBLOCK
def rd(p,wait=0.15):
    fd=os.open(f'/dev/robot/{p}', os.O_RDONLY|NB)
    out=b''; t0=time.time()
    while time.time()-t0<wait:
        r,_,_=select.select([fd],[],[],0.05)
        if r:
            try:
                d=os.read(fd,8192)
                if d: out=d
            except BlockingIOError: pass
    os.close(fd)
    return out.decode().strip()
def wr(p,v):
    fd=os.open(f'/dev/robot/{p}', os.O_WRONLY|NB)
    os.write(fd, f'{v}\n'.encode()); os.close(fd)
def sense():
    try: beams=[float(x) for x in rd('d5').split(',')]
    except: beams=[-2.0]*16
    def f(p,d=0.0):
        try: return float(rd(p,0.05))
        except: return d
    imu=rd('d0',0.05)
    try: ax,ay,wz=[float(x) for x in imu.split(',')]
    except: ax=ay=wz=0.0
    return dict(beams=beams,ax=ax,ay=ay,wz=wz,speed=f('d2'),head=f('d3'),
                d1=f('d1'),d6=f('d6'),d8=rd('d8',0.05))
def show(tag=''):
    s=sense()
    b=' '.join(f'{x:4.1f}' for x in s['beams'])
    print(f"{tag} hd={s['head']:6.1f} v={s['speed']:5.2f} wz={s['wz']:5.2f} d1={s['d1']:.0f} d6={s['d6']:.0f} {s['d8']}\n   {b}", flush=True)
class Driver:
    def __init__(self):
        self.stop=False; self.th=None; self.cmds={'d4':'0','d7':'0'}
    def _pump(self,hz=50):
        while not self.stop:
            for p,v in self.cmds.items():
                try: wr(p,v)
                except Exception: pass
            time.sleep(1.0/hz)
    def start(self,d4,d7,hz=50):
        self.stop=False; self.cmds={'d4':str(d4),'d7':str(d7)}
        self.th=threading.Thread(target=self._pump,args=(hz,)); self.th.start()
    def set(self,d4=None,d7=None):
        if d4 is not None: self.cmds['d4']=str(d4)
        if d7 is not None: self.cmds['d7']=str(d7)
    def halt(self):
        self.set(0,0); time.sleep(0.3); self.stop=True
        if self.th: self.th.join()
        self.th=None
