import csv
def load(fn):
    out=[]
    try:
        with open(fn) as f:
            for r in csv.reader(f):
                if len(r)<9: continue
                out.append((float(r[0]),float(r[2]),float(r[3]),float(r[4]),r[7],[float(x) for x in r[8].split(';')]))
    except: pass
    return out
